1246	        var min_delay: ?u64 = null;
1247	
1248	        var it = self.images.iterator();
1249	        while (it.next()) |entry| {
1250	            const img: *Image = entry.value_ptr;
1251	
1252	            // The gates below mirror Kitty's image_is_animatable.
1253	
1254	            // No animation state was ever attached (plain image).
1255	            const anim = img.animation orelse continue;
1256	
1257	            // Stopped is the initial state of every animation: frames
1258	            // then only change client-driven (a=a c=N), never by time.
1259	            if (anim.state == .stopped) continue;
1260	
1261	            // Only the root frame exists; there is nothing to advance
1262	            // to yet even in the running state.
1263	            if (anim.frames.items.len == 0) continue;
1264	
1265	            // Unplaced images don't animate. This is our simpler
1266	            // approximation of Kitty's "is actually drawn" visibility
1267	            // gate; it is what stops an image that was transmitted but
1268	            // never placed from waking the renderer forever.
1269	            if (img.metadata.placement_count == 0) continue;
