1280	            // no frame can ever be displayed, so the animation can
1281	            // never advance. This also guards the gapless-skip loop
1282	            // below from never terminating.
1283	            if (anim.durationMs() == 0) continue;
1284	
1285	            // A finite loop budget (a=a v=N) that ran out on an
1286	            // earlier tick froze playback on the last frame for good.
